// Exact section-return accelerator for BB429.next, using A=2u+6, R=2u+w.
// All rank increments are constants. Finite integer interval certificates
// are generated by propagating A(R+4i)=A(R)-4Pi, P>=0.
#include <algorithm>
#include <bit>
#include <cassert>
#include <cstdint>
#include <cstdio>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <string>
#include <chrono>
using U=uint64_t; using W=__uint128_t; using I=int64_t;
constexpr U MAX_R=U(1)<<61;
constexpr U INF=MAX_R;
struct State { U A,R; };
struct Block { State end; U length,horizon; enum Status{Reset,Halt,Escape,Limit} status; };
U ufloorlog(U x){return std::bit_width(x)-1;}
// A and R are bounded by MAX_R+6, and the intermediate comparisons use 128 bits.
U first_burst(State s) {
    U q=(s.R+6)/s.A;
    U k=q?ufloorlog(q):0;
    while((W(s.A)<<(k+1))<=W(s.R)+3*(k+1)+6)++k;
    while(k && (W(s.A)<<k)>W(s.R)+3*k+6)--k;
    return k;
}
Block next_reset(State s, U horizon=INF, U lim=1000000) {
    U P=0,len=0;
    auto cap=[&](I g,I upper){ if(horizon) horizon=std::min(horizon,U(W(upper-g)/(4+W(8)*P))); };
    auto f=[&](U k){
        s.A<<=k; s.R+=3*k; len+=k;
        if(horizon && P){W pp=W(P)<<k;if(pp>MAX_R){horizon=0;P=0;}else P=U(pp);}
    };
    auto reset=[&](U A,U inc){s.A=A;s.R+=inc;++len;return Block{s,len,horizon,Block::Reset};};
    while(len<lim) {
        if(s.R>=MAX_R)return {s,len,horizon,Block::Limit};
        U k=first_burst(s);f(k);
        I g=I(s.R)-2*I(s.A)+12;
        assert(g<=2);
        if(g==2){horizon=0;return reset(6,16);}
        if(g==1){horizon=0;return reset(28,23);}
        if(g==0){horizon=0;return reset(6,12);}
        if(g==-1)return {s,len,0,Block::Halt};
        if(g==-2){horizon=0;return reset(6,10);}
        if(g==-3){horizon=0;return reset(6,5);}
        switch(U(g)&3){
        case 0:cap(g,-4);return reset(28,20);
        case 2:cap(g,-6);return reset(6,10);
        case 1: {
            U u=(s.A-6)/2,w=s.R-s.A+6;
            if(w==1){horizon=0;return reset(28,31);}
            if(u>=19 && (u&3)==3 && w==u+12)return {s,len,0,Block::Escape};
            cap(g,-7);s.A=2*s.A-s.R+9;s.R+=11;break;
        }
        default: {
            U u=(s.A-6)/2,w=s.R-s.A+6;
            if(u>=17 && (u&3)==1 && w==u+8)return {s,len,0,Block::Escape};
            cap(g,-5);s.A=2*s.A-s.R+1;s.R+=7;break;
        }}
        ++len;
        if(horizon){if(P>MAX_R/2){horizon=0;P=0;}else P=2*P+1;}
    }
    return {s,len,horizon,Block::Limit};
}
bool same_type(State s,State t){return s.A==t.A&&(s.R&3)==(t.R&3);}
void varint(FILE* f,U n){while(n>=128){fputc((n&127)|128,f);n>>=7;}fputc(n,f);}
void certificate(FILE*f,U len,U count,U quarter){if(f){varint(f,len);varint(f,count);varint(f,quarter);}}
int main(int argc,char**argv){
    if(argc!=3&&argc!=6){std::cerr<<"usage: rank_return budget certificate.bin|- [u w macrotime]\n";return 2;}
    U budget=std::stoull(argv[1]),tm=0; State s{6,0};
    if(argc==6){U u=std::stoull(argv[3]),w=std::stoull(argv[4]);s={2*u+6,2*u+w};tm=std::stoull(argv[5]);}
    FILE* f=std::string(argv[2])=="-"?nullptr:fopen(argv[2],"wb");
    if(std::string(argv[2])!="-"&&!f)throw std::runtime_error("cannot create certificate");
    auto start=std::chrono::steady_clock::now();
    for(U i=1;i<=budget;++i){
        Block b=next_reset(s);U length=b.length,hor=b.horizon;
        if(b.status==Block::Reset&&!same_type(s,b.end)&&hor){
            Block c=next_reset(b.end,hor);
            if(c.status==Block::Reset&&same_type(s,c.end)){length+=c.length;b=c;hor=c.horizon;}
        }
        if(b.status!=Block::Reset){
            if(length)certificate(f,length,1,0);
            std::cout<<"STOP "<<b.status<<" block="<<i<<" time="<<tm+length<<" u="<<(b.end.A-6)/2<<" w="<<b.end.R-b.end.A+6<<std::endl;
            if(f)fclose(f);return 0;
        }
        U d=b.end.R-s.R,n=1;
        if(same_type(s,b.end)&&hor)n=hor/(d/4)+1;
        if(n>(MAX_R-s.R)/d)n=std::max<U>(1,(MAX_R-s.R)/d);
        certificate(f,length,n,n>1?d/4:0);
        s=b.end;s.R+=(n-1)*d;tm+=n*length;
        if(i%1000000==0||i==budget){if(f)fflush(f);std::cout<<i<<" time="<<tm<<" u="<<(s.A-6)/2<<" w="<<s.R-s.A+6<<" seconds="<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<std::endl;}
        if(s.R>=MAX_R){std::cout<<"rank cap reached\n";break;}
    }
    if(f)fclose(f);
}
